t.script:
const TEMPLATE_ID = ;
const SIGN_ITEMS = ;

const pdfjsLib = window['pdfjs-dist/build/pdf'];
pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';

let pdfDoc = null;
let canvasList = [];

async function renderPDF(url, canvasContainer) {
    const loadingTask = pdfjsLib.getDocument(url);
    pdfDoc = await loadingTask.promise;
    for (let i = 1; i <= pdfDoc.numPages; i++) {
        await renderPage(i, canvasContainer);
    }
}

async function renderPage(num, canvasContainer) {
    const page = await pdfDoc.getPage(num);
    const scale = 1.5;
    const viewport = page.getViewport({scale: scale});
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    canvas.height = viewport.height;
    canvas.width = viewport.width;
    canvas.style.width = '100%';
    canvasContainer.appendChild(canvas);
    canvasList.push({canvas, viewport, pageNum: num});
    const renderContext = {
        canvasContext: ctx,
        viewport: viewport
    };
    await page.render(renderContext).promise;
}

renderPDF('/sign/template/' + TEMPLATE_ID + '/pdf', document.getElementById('o_sign_root'));
